import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';

import 'seed_exercises.dart';
import 'tables.dart';

// This file is generated by build_runner.
part 'app_database.g.dart';

/// The local SQLite database. All workout data is stored on the phone.
@DriftDatabase(tables: [Exercises, Workouts, WorkoutExercises, SetEntries])
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(driftDatabase(name: 'fitness_logger'));

  // Increase this number when the table structure changes later.
  @override
  int get schemaVersion => 1;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        // Runs only the first time the database is created:
        // create all tables, then add the starter exercises.
        onCreate: (m) async {
          await m.createAll();
          await seedExercises(this);
        },
        beforeOpen: (details) async {
          // Turn on foreign keys so cascade deletes work.
          await customStatement('PRAGMA foreign_keys = ON');
        },
      );
}